import type { ResearchPost } from './fleet-data';

const sources: ResearchPost['sources'] = [
  { name: 'NIST Cybersecurity Framework 2.0', url: 'https://www.nist.gov/cyberframework', note: 'Risk-management guidance for identifying, protecting, detecting, responding, and recovering from operational risk.', kind: 'Global comparison' },
  { name: 'NIST Privacy Framework', url: 'https://www.nist.gov/privacy-framework', note: 'A structured reference for privacy-risk identification and data-processing decisions.', kind: 'Global comparison' },
  { name: 'Philippine Data Privacy Act of 2012', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Primary Philippine privacy source for personal-information processing and accountability.', kind: 'Philippines' },
  { name: 'FTC Protecting Personal Information', url: 'https://www.ftc.gov/business-guidance/resources/protecting-personal-information-guide-business', note: 'Official guidance on access, retention, disposal, and service-provider safeguards.', kind: 'Global comparison' },
  { name: 'ILO Working from home guide', url: 'https://www.ilo.org/publications/working-home-guide', note: 'International reference for organizing and governing remote work.', kind: 'Global comparison' },
  { name: 'Philippine Telecommuting Act', url: 'https://lawphil.net/statutes/repacts/ra2018/ra_11165_2018.html', note: 'Primary Philippine legal text concerning private-sector telecommuting arrangements.', kind: 'Philippines' },
];

type Topic = { slug: string; title: string; excerpt: string; question: string; finding: string; headings: string[]; paragraphs: string[] };

const topics: Topic[] = [
  { slug: 'offshore-call-center-queue-acceptance-evidence', title: 'Offshore call center queue acceptance: what evidence shows a handoff is ready?', excerpt: 'A bounded study of the evidence a buyer should inspect before accepting a Philippines-based support queue from transition into live work.', question: 'What evidence shows that an offshore call center queue is ready to move from transition into accountable live handling?', finding: 'Acceptance should be a decision about demonstrated work, controls, and ownership, not a date on a project calendar.', headings: ['Question and operational finding','The unit of evidence is a queue, not a slide deck','Testing the Philippines delivery context','Separating observation from acceptance judgment','What the evidence cannot establish','Conclusion: accept a bounded promise'], paragraphs: [
    'A queue handoff is often described as complete when training is finished, credentials exist, and a launch meeting has occurred. Those events are useful, but none answers the buyer’s real question: can the assigned Philippines-based team handle the stated request types, use the permitted systems, recognize exceptions, and leave an accountable next step? The research question for this report is therefore narrower than whether a provider is generally capable. It asks what evidence supports acceptance of one defined queue at one point in time. The finding is that acceptance is a claim about demonstrated work and controlled boundaries. It needs sample records, scored scenarios, access evidence, escalation acknowledgements, and a named owner for unresolved gaps. [1][3][4]',
    'Define the unit before reviewing results. The unit can be a request type during a stated period, with its channel, language, system, permitted action, and escalation outcome recorded. A training attendance sheet is evidence that people attended; it is not evidence that they can safely resolve an order question or stop at a manager-only decision. A clean demonstration is also incomplete if it excludes an ambiguous request, a missing record, a customer correction, or a system outage. Inspect ordinary cases and boundary cases separately. Record the selection method, missing observations, reviewer identity, and disagreement rather than converting an unknown into a pass. This is consistent with control frameworks that treat identification, protection, and assessment as connected activities rather than a one-time declaration. [1][2]',
    'For a Philippines-based queue, acceptance should include the actual work location and fallback assumptions. If representatives work from an office, home, or an approved alternate location, the review should identify which systems, devices, networks, recording paths, and privacy restrictions apply in each state. A backup internet connection proves only that a connection may be available; it does not prove that telephony routes, customer records save, authentication works, or the client owner is reachable. The same applies to staffing: a roster does not prove shift coverage when leave, coaching, connectivity loss, or a language-specific overflow occurs. Ask to see one normal shift handoff, one exception handoff, and one recovery note. Keep legal interpretation with qualified owners; the evidence here is operational, not a universal compliance opinion. [3][5][6]',
    'Acceptance becomes more reliable when facts and judgments are written in different columns. Facts might include that 18 of 20 sampled requests followed the approved answer, two required correction, one escalation lacked acknowledgement within the agreed window, and the assigned reviewer could access only the intended application. Analysis might infer that the escalation field is not yet reliable. A decision might accept routine email handling while holding payment-adjacent calls out of scope. That staged decision is stronger than a single green status. Run a small controlled test with a fixed sample, the same scorecard, and a review date. If the score changes after coaching, do not claim the coaching caused it when staffing mix, system latency, or request mix also changed. [1][4]',
    'This design cannot establish future performance, provider-wide quality, legal sufficiency in every customer jurisdiction, or continuous availability. A small sample can expose an unclear definition or a dangerous role boundary, but it is not automatically a population estimate. A launch week may be unusually attentive. A successful role-play may not predict a distressed caller, a policy change, or a prolonged outage. The buyer should also avoid treating the absence of an incident as proof that controls work; absence may reflect low volume or unobserved failure. State the queue, period, exclusions, and open risks beside the decision so a later reviewer knows what was actually accepted.',
    'The evidence-led conclusion is to accept a narrow operational promise only when the queue has a defined scope, scored ordinary and exception work, verified access boundaries, visible Philippines delivery assumptions, acknowledged escalation ownership, and a dated review of remaining gaps. Acceptance is reversible: expand the request types only after new evidence supports them. A representative can perform approved work and raise uncertainty; a client-side or authorized manager must decide restricted actions, policy exceptions, and whether the risk is acceptable. That separation lets a buyer move forward without pretending that a launch ceremony proves readiness. [1][2][3]'
  ] },
  { slug: 'philippines-call-center-multilingual-quality-evidence', title: 'Philippines call center multilingual quality: what should a buyer actually test?', excerpt: 'A research question about language coverage, comprehension, routing, and safe fallback in Philippines-based customer support.', question: 'What evidence supports a language-coverage promise for a Philippines call center beyond a label on a staffing plan?', finding: 'Language capability is a measured queue property: comprehension, accuracy, writing, routing, and fallback must be tested together.', headings: ['The question is coverage, not fluency branding','A language sample needs a defined frame','Where routing and comprehension fail','Decision boundaries for representatives','Limitations of scenario testing','Conclusion: make the promise narrow and testable'], paragraphs: [
    'A language promise can hide several different claims. It may mean that someone can greet a customer, understand a routine request, write a concise note, explain a changed policy, or recognize when comprehension is failing. These are not interchangeable. The research question is what evidence supports multilingual quality in a Philippines-based support queue. The finding is that a country-level reputation or a self-described language skill does not establish live coverage. A buyer should define the language, channel, request types, shift, quality threshold, and fallback owner, then test the same cases across candidates. Language quality is part of safe resolution because a misunderstood account detail can create repeat contact, disclosure risk, or an incorrect promise. [1][2][3]',
    'Build the evidence frame before recruiting a score. Record requested language, language delivered, queue wait, transfer, comprehension check, answer accuracy, writing quality, and outcome for a stated sample. Separate routine requests from technical terms, changed policies, sensitive topics, and cases requiring a specialist. If only successful interactions are reviewed, the study misses the cases that trigger transfer or abandonment. Review both audio and the resulting case note where the channel allows it. The sample should say whether reviewers are native speakers, trained assessors, or operational managers; their role affects what their scores can mean. Missing language observations remain missing rather than being inferred from a general agent profile. [1][4]',
    'Routing is part of language quality. A preferred-language request may arrive outside the staffed window, after a policy changes, or with a subject that needs an owner unavailable in that language. Examine the fallback: does the representative explain the limitation, preserve the minimum context, and route to an acknowledged owner without exposing extra data? For Philippines delivery, compare ordinary and peak shifts and document approved locations and system access. An alternate route can reduce customer repetition, but a transfer alone is not a successful outcome. Compare correction, repeat explanation, transfer delay, and safe closure by request type. The ILO and Philippine telecommuting sources are useful context for work organization, but neither proves an individual queue’s language capacity. [5][6]',
    'Representatives may use approved language support and state when they cannot safely continue; they must not claim comprehension they do not have or improvise a policy translation. The client or designated policy owner decides whether a translated answer is approved and what happens when no qualified language owner is available. In a controlled study, use matched scenarios before and after one routing change. Keep the scoring dimensions separate: comprehension, factual accuracy, tone, written note, escalation choice, and time to qualified owner. A combined score can conceal a serious failure in one dimension. Report observed facts first, then the interpretation and the decision boundary.',
    'Scenario results do not predict every live conversation. They may understate stress, accents, code-switching, poor audio, cultural context, or an unusual product term. A short test cannot prove continuous availability, legal adequacy, or customer satisfaction. Nor should a low score automatically identify an individual cause; the problem may be routing, answer coverage, system latency, or an unclear policy. Repeat the test after material policy, staffing, or channel changes. Preserve the scenario set and version so later scores are comparable, while limiting customer data in test material under purpose and access principles. [2][3][4]',
    'The conclusion is to publish only a narrow, measured coverage promise: which language, which hours, which request types, which channel, and which fallback. Require evidence for comprehension and safe routing rather than relying on a broad workforce statistic. A Philippines-based team can be evaluated fairly when the buyer tests real queue conditions, gives representatives a clear stop rule, and keeps translation and policy ownership explicit. The result is a safer promise and a more useful hiring decision, not a claim that one test settles all language performance. [1][2][3]'
  ] },
  { slug: 'offshore-call-center-occupancy-variance-study', title: 'Offshore call center occupancy variance: what staffing evidence can reveal', excerpt: 'A bounded study of occupancy, arrival patterns, shrinkage, and customer impact for a Philippines-based support queue.', question: 'What can occupancy variance tell a buyer about staffing risk without turning one metric into a staffing promise?', finding: 'Occupancy describes the relationship between offered work and available handling capacity; it does not by itself prove service, wellbeing, or future coverage.', headings: ['Question and finding','Define the denominator before comparing shifts','Read occupancy beside customer work','Philippines coverage and handoff effects','What a variance study cannot prove','Conclusion: use occupancy as a signal'], paragraphs: [
    'Occupancy is attractive because it compresses a busy queue into a simple percentage. That simplicity is also the risk. The research question is what occupancy variance can reveal about staffing in an offshore support operation. The finding is that occupancy is a signal about the relationship between offered work and available handling capacity, not a quality score or a guarantee of coverage. A buyer needs definitions for interval, offered contacts, productive handling, after-call work, unavailable time, shrinkage, and channel mix. Without those definitions, two teams can report different numbers for the same period and make a false comparison. A high figure may signal overload; a low figure may reflect missing work, poor routing, or excessive unavailable time. [1][4]',
    'Study the denominator first. For each interval, reconcile telephony or ticket records with schedule, adherence, breaks, coaching, training, absence, system downtime, and transfers. Separate voice from asynchronous work because an email queue does not behave like a call queue. Report the queue, date range, timezone, language, and excluded intervals. In a Philippines operation, overnight local coverage may coincide with a client daytime peak, while local holidays, weather, or connectivity events can alter the observed pattern. The evidence should show whether a variance is a short spike, a repeated shift pattern, or a data-quality artifact. A number without its record path is an observation with uncertain meaning, not a staffing recommendation. [1][5][6]',
    'Interpret occupancy beside customer outcomes. Compare wait, abandonment, transfer, repeat contact, case age, correction, and safe closure by request type. If occupancy falls after a routing change, ask whether contacts moved to another queue. If it rises while wait stays stable, the team may be handling more complex requests or doing more after-call work. Use matched periods where possible, but do not call a before-and-after relationship causal when policy, product, volume, or supervisor coverage also changed. A representative should record the work and signal overload; the manager decides whether to change schedule, scope, routing, or escalation. Customers should not bear the hidden cost of a target that rewards speed while repeat work grows. [1][2][4]',
    'Coverage evidence must include handoffs and recovery. A schedule can look adequate while a language-specific owner is absent, an escalation queue ages, or a backup location cannot reach the client system. Inspect peak intervals, shift change, and one disruption scenario. For remote or hybrid Philippines work, document approved location, device, connectivity, privacy, and owner contact rather than assuming a spare link solves the problem. The ILO guide and Philippine telecommuting law provide context for organizing remote work, but they do not establish the capacity or service outcome of this queue. Those facts require direct records from the proposed operation. [5][6]',
    'This study cannot identify a universal ideal occupancy, forecast demand without reliable inputs, or prove that a particular staffing level will work in a future season. A short period can be distorted by campaigns, outages, unusual absence, or a changed product. Aggregate occupancy can hide a small group carrying the hardest work. It also cannot establish worker wellbeing from a single operational metric; that requires an appropriately designed people and health review. Treating a high number as proof of productivity or a low number as proof of waste would exceed the evidence. Preserve uncertainty and investigate the queue-specific cause.',
    'The evidence-led conclusion is to use occupancy variance as an investigation trigger. Define the measure, reconcile its denominator, segment by request and shift, read it with customer outcomes, and inspect handoff and recovery states. Then make one controlled change with an accountable owner and a review date. A Philippines-based queue should be accepted on the evidence of its actual interval behavior and role boundaries, not on an abstract target. This approach lets a buyer distinguish demand, capacity, routing, and data-quality problems before changing staffing. [1][2][4]'
  ] },
  { slug: 'call-center-refund-escalation-control-study', title: 'Call center refund escalation controls: where should the decision stop?', excerpt: 'A research-led examination of refund requests, identity checks, evidence, and client-owner decisions in outsourced support.', question: 'What evidence shows that an outsourced queue can route refund requests safely without giving representatives an unauthorized financial decision?', finding: 'Safe refund handling separates verification, fact gathering, permitted status updates, and the restricted approval decision.', headings: ['The research question','Map the refund decision into observable stages','Evidence and minimum necessary context','The representative boundary','Limitations and false confidence','Conclusion: route the decision, do not blur it'], paragraphs: [
    'A refund request is not a single task. It can involve identity, order status, delivery evidence, policy interpretation, fraud signals, payment timing, and an approval authority. The research question is what evidence shows that an outsourced call center can handle the request safely. The finding is that the queue should be assessed on its separation of stages: verify the customer, gather permitted facts, explain the next step, record the request, and route the restricted decision. A fast answer is not necessarily a safe answer. The study should inspect ordinary eligible requests, disputed delivery, duplicate claims, and cases where records conflict. Each cohort tests a different boundary. [1][2][3]',
    'Write the decision tree as observable events rather than broad instructions. The record should show the request, verification result, order or case identifier, permitted evidence, policy version, action taken, escalation owner, acknowledgement, and customer-facing next step. Do not copy unnecessary payment data into notes. Compare the written record with the system event and the final decision. A representative may update an approved status or collect an explanation if the role permits it; the authorized owner decides exception, credit, refund, or fraud disposition. If a system automatically approves a category, document that rule and its owner rather than treating automation as representative authority. [2][3][4]',
    'The evidence sample should test data minimization and access as well as outcome. Review which fields the Philippines-based representative can see, which exports are possible, how recordings are handled, and whether the escalation includes only what the receiving owner needs. A request sent to an unacknowledged inbox is not a controlled escalation. Trace returned requests and repeat contacts because they reveal whether the customer was asked to repeat the story or whether the decision owner was unclear. For remote work, verify approved location, devices, and recovery contact. Privacy and security guidance can frame the control, but direct queue records establish whether the intended boundary operates. [1][3][5]',
    'A good controlled test changes one rule, such as the required evidence field or acknowledgement trigger, and compares the same request cohorts before and after. Measure safe verification, incomplete packets, decision age, repeat explanation, unauthorized action attempts, and correction. Do not reward representatives for avoiding escalations if the queue then makes unsupported promises. Do not infer fraud from a failed verification without distinguishing mismatch, outage, unavailable factor, and deliberate risk. The client owner should review ambiguous policy and exception cases; the frontline role should stop disclosure and explain the approved path. Facts, analysis, and action should remain visibly distinct.',
    'The study cannot prove that every fraudulent request will be detected, that a policy is lawful in every jurisdiction, or that a low correction rate means no risky action occurred. Rare events require careful sampling and may not appear in a routine review. A clean workflow diagram does not prove that staff follow it under pressure. A single audit cannot establish continuous access control or future system behavior. State the tested products, time window, request types, exclusions, and reviewer qualifications. Escalate legal, payment-network, and fraud questions to the appropriate authorized owner rather than presenting operational research as legal advice. [2][3][4]',
    'The conclusion is to keep the refund decision visibly owned. The queue can verify, gather, explain, and route within its role, while an authorized owner decides exceptions and financial outcomes. Require direct evidence for each stage, least-privilege access, acknowledged handoffs, and repeat testing after policy or system changes. A Philippines-based support operation becomes easier to assess when the buyer can see not only whether requests were resolved, but also where the representative stopped and why. [1][2][3]'
  ] },
  { slug: 'offshore-call-center-crm-note-completeness-research', title: 'Offshore call center CRM notes: what makes a customer record decision-ready?', excerpt: 'A study of note completeness, minimum necessary context, ownership, and repeat-contact evidence in outsourced support.', question: 'What evidence shows that a CRM note will help the next owner act without creating unnecessary privacy exposure?', finding: 'A useful note preserves the decision-relevant context, current owner, next step, and boundary while avoiding irrelevant or excessive customer detail.', headings: ['Question and finding','Completeness is a purpose question','Test notes against the next decision','Privacy and Philippines work context','What note metrics miss','Conclusion: write for the next owner'], paragraphs: [
    'A note can be long and still be unusable. It can also be short enough to create repeat contact, an incorrect promise, or unnecessary exposure. The research question is what makes an outsourced call center CRM note decision-ready. The finding is that completeness depends on the next authorized decision: request, verified context, action already taken, unresolved dependency, owner, due point, and customer-facing expectation. It does not mean copying the entire interaction. The study should compare routine, escalated, disputed, and returned cases because each needs a different minimum record. [1][2][3]',
    'Define required fields by request type and test missing values as evidence. A routine status request may need order reference, status source, answer, and next step. An escalation may also need decision requested, urgency reason, receiving owner, acknowledgement, and permitted customer update. A complaint may require the customer’s stated issue and preservation route without unnecessary sensitive detail. Reviewers should score factual accuracy, action traceability, ownership, date or due point, and data minimization separately. A completion percentage that counts every filled field can look healthy while the most important field is wrong. Keep the schema and policy version visible so a later reader knows what “complete” meant. [2][4]',
    'Test the note with a blinded next-owner exercise. Give a manager or specialist the note without the original call and ask what decision can safely be made, what remains unknown, and what customer update is permitted. Record clarification requests, repeat explanations, incorrect assumptions, and time to acknowledged action. Compare notes written on ordinary and exception work. In a Philippines-based team, include shift handoff and time-zone context where it affects the due point, but do not use geography as a substitute for an owner. Representatives may document facts and flag uncertainty; the client or authorized specialist decides restricted outcomes. [1][3][5]',
    'Privacy controls belong inside the note design. Map which fields are visible to frontline staff, supervisors, specialists, and exports. A note that includes full payment details or unrelated health information may be “complete” in a clerical sense but unsafe in purpose and access. Review retention and deletion pathways for notes, recordings, attachments, and copied messages. Remote work requires approved location, device, and access assumptions to be explicit. Philippine privacy and telecommuting sources help identify duties and context, while direct sample records show whether the team applies the intended minimum. [3][4][6]',
    'Note metrics cannot prove customer satisfaction, factual truth, or future usefulness by themselves. A high completion rate may reflect box ticking. A short note may be correct for a simple request. A reviewer who knows the original interaction may over-credit missing context. The test should therefore include independent readers and source-record comparison. Results are limited to the schema, queue, period, and sampled request types. They do not establish that every representative will write equally well or that a new product will fit the current fields. State uncertainty rather than using a neat score as a universal benchmark.',
    'The conclusion is to design notes backward from the next authorized decision. Require minimum necessary context, factual action, current owner, dependency, due point, and safe customer expectation; then verify those elements through a next-owner test. Use correction and repeat-contact evidence to refine the schema, not to punish representatives for escalating uncertainty. An offshore queue is better controlled when the CRM is a handoff instrument with a clear role boundary, not a storage place for everything heard on a call. [1][2][3]'
  ] },
  { slug: 'philippines-call-center-disaster-recovery-tabletop-evidence', title: 'Philippines call center disaster-recovery tabletop: what can the exercise prove?', excerpt: 'A research question about power, connectivity, systems, people, and customer communication during a Philippines-based support disruption.', question: 'What does a disaster-recovery tabletop actually prove about continuity in a Philippines call center?', finding: 'A tabletop can expose unclear dependencies and decisions; it cannot prove that live recovery will succeed without a tested technical and operational path.', headings: ['Question and bounded finding','Model the customer-impacting dependency chain','Run the scenario across locations and owners','Observe decisions, not performance theatre','Tabletop limitations','Conclusion: turn findings into a dated test'], paragraphs: [
    'A continuity document can name backup power, alternate connectivity, remote work, and escalation contacts without showing how a customer queue behaves when several dependencies fail together. The research question is what a disaster-recovery tabletop can prove for a Philippines call center. The finding is that the exercise can reveal missing owners, assumptions, and decision conflicts; it cannot prove live recovery by itself. A useful scenario begins with customer impact, such as calls failing to route or records not saving, and traces the chain through people, location, device, network, telephony, application, privacy, communication, and recovery ownership. [1][5][6]',
    'Define the scenario and evidence before starting. State the affected queue, time, language, system, disruption, customer promise, and allowed assumptions. Ask who detects the event, who can authorize fallback, what the representative tells the customer, where the case is recorded, and when the client is updated. Include a local office interruption, a remote connectivity failure, a platform outage, and a missing-owner scenario because each tests a different dependency. Record decisions and elapsed acknowledgement rather than rewarding confident talk. If an answer is unknown, capture it as an action with an owner and due point. [1][4]',
    'For Philippines delivery, compare approved office, home, and alternate arrangements without assuming that movement is automatically permitted. Verify device control, authentication, recording, customer-data visibility, privacy during relocation, power, connectivity, and the queue’s overflow owner. A backup link proves only one path; it does not prove the application or voice route works. The Philippine telecommuting source and ILO guidance provide context for remote arrangements, while the exercise needs direct confirmation of the proposed operation. Keep representatives responsible for approved fallback steps and customer-safe notes; managers decide scope changes, public messages, and recovery declarations. [3][5][6]',
    'Observers should ask for evidence at each decision point: an alert, a system status, an approved contact, a routed interaction, a saved record, or an acknowledged handoff. Avoid turning the tabletop into a script in which every participant already knows the answer. Inject a changed condition, such as the first fallback owner being unavailable, to test whether ownership is resilient. Afterward, separate facts from analysis: “the alternate queue was not provisioned” is a fact; “the continuity plan is immature” is an interpretation. Assign one corrective change and test it technically or operationally before claiming improvement. [1][2]',
    'A tabletop cannot establish annual availability, recovery time under real load, privacy compliance in every jurisdiction, or the behavior of every representative. Participants may behave differently from an overnight shift during an actual outage. A test that uses no real routing, authentication, or record-saving path may expose planning gaps but cannot validate the technology. Weather, power, carrier, staffing, and client availability can change. Preserve the scenario version, participants, exclusions, open risks, and next exercise date. Never treat a completed workshop as evidence that an untested system will recover.',
    'The conclusion is to use the tabletop as a discovery instrument, then convert material findings into dated drills with named owners and measured evidence. A Philippines-based support queue should be able to explain who protects customer data, who authorizes fallback, how the interaction is recorded, and what promise is made while recovery is uncertain. Continuity is a chain, and the weakest untested dependency controls the claim. [1][3][5]'
  ] },
  { slug: 'call-center-accessibility-support-evidence-study', title: 'Call center accessibility support: what should an outsourced queue demonstrate?', excerpt: 'A bounded study of accessible communication, routing, representative boundaries, and evidence for customer-support decisions.', question: 'What evidence shows that an outsourced call center can support accessibility needs without claiming a capability it has not tested?', finding: 'Accessibility is a request-specific service condition requiring tested channels, communication adjustments, escalation, and honest limits.', headings: ['The question and finding','Define the customer need and channel','Test adjustments without exposing excess data','Role boundaries and safe escalation','Limits of accessibility evidence','Conclusion: promise the tested path'], paragraphs: [
    'Accessibility claims are often broader than the operational path behind them. A queue may offer voice, email, chat, relay interaction, written follow-up, or a slower specialist route, but availability differs by hour, request type, system, and trained owner. The research question is what an outsourced support operation should demonstrate. The finding is that accessibility is a service condition to be tested, not a marketing adjective. Define the customer need, channel, language, response expectation, data requirement, and fallback. Evaluate whether the customer can complete the intended task safely, not merely whether a representative used a polite greeting. [1][2][3]',
    'Start with a scenario inventory that includes routine information, account verification, a changed policy, a technical problem, and an escalation. Document the permitted adjustment and what success means for each. Review waiting, transfer, comprehension, written accuracy, record note, and next-step clarity. Do not ask a customer to reveal more health or disability information than the task requires. A representative may ask what communication adjustment is needed within an approved script and route a barrier; an authorized owner decides an accommodation outside the documented service path. Separate direct evidence from assumptions about a customer population. [2][4]',
    'Test the channels and tools the Philippines-based team will actually use. An accessible channel is not established by a link that the assigned shift cannot monitor or a form that the queue cannot read. Review device, application, recording, captioning or relay assumptions, privacy during remote work, and handoff to a qualified owner. Observe a failed path as well as a successful one: what does the representative say when the requested adjustment is unavailable? Does the note preserve the customer’s need without unnecessary sensitive detail? The ILO and privacy sources add context, but the queue must provide direct evidence of its own route. [3][5][6]',
    'A controlled exercise should use consistent scenarios and independent reviewers who understand the relevant communication requirement. Score whether the adjustment was offered, whether the customer could understand the next step, whether the record captured the minimum needed, and whether ownership was acknowledged. Do not combine all dimensions into a single pass. If an accessible route takes longer, measure delay and repeat contact without assuming that speed should override completion. Keep facts, interpretation, and recommendation apart, especially where the service path may need a policy or product decision outside frontline authority. [1][2]',
    'The evidence cannot prove universal accessibility, satisfaction, legal compliance, or the performance of every channel under every condition. Scenario reviewers may miss lived experience. A route that works for one need may fail for another. A Philippines-based queue may also depend on client systems, language coverage, vendor technology, and shift ownership. Name the tested needs, channels, period, and exclusions, and involve qualified accessibility and legal reviewers where the decision warrants it. Do not treat absence of a complaint as proof that customers encountered no barrier. [3][4]',
    'The conclusion is to promise the tested path precisely: channel, hours, adjustment, request types, privacy boundary, fallback, and owner. Give representatives a safe stop-and-escalate rule and measure successful completion rather than only response speed. An offshore team can provide respectful, useful support without overstating capability when its evidence describes what customers can actually do and where the organization must make the next decision. [1][2][3]'
  ] },
  { slug: 'offshore-call-center-seasonal-surge-readiness-study', title: 'Offshore call center seasonal surge readiness: what evidence matters before volume rises?', excerpt: 'A research-led examination of demand assumptions, training, overflow, quality, and continuity for Philippines-based seasonal support.', question: 'What evidence shows that an offshore call center can absorb a seasonal surge without shifting hidden work or control failures to customers?', finding: 'Surge readiness depends on tested queue behavior, decision boundaries, and recovery capacity, not a headcount promise alone.', headings: ['Research question and finding','Turn a forecast into observable scenarios','Study new staff and changed work','Overflow, Philippines coverage, and recovery','What the study cannot forecast','Conclusion: expand from evidence'], paragraphs: [
    'Seasonal readiness is commonly reduced to adding people. That misses answer changes, training time, supervisor span, system capacity, language mix, escalation age, and the work created by incomplete resolution. The research question is what evidence shows that an offshore queue can absorb a surge safely. The finding is that readiness is demonstrated by scenario performance under changed demand, with clear boundaries and recovery ownership. Define the expected request types, arrival pattern, channel, coverage window, response promise, overflow, and customer-impacting failure. A roster is an input; it is not proof that the queue can resolve the work. [1][4]',
    'Translate assumptions into scenarios. Model ordinary peak volume, a changed policy, a difficult request, a language-specific spike, system latency, and a missing specialist. For each, record wait, abandonment, transfer, repeat contact, case age, correction, escalation acknowledgement, and safe closure. Keep projected values separate from observed values. If historical data is sparse, say so and use ranges rather than invented precision. In a Philippines operation, align local shift, client timezone, holidays, approved locations, and backup owners. The scenario should also test after-call work and handoff; hidden backlog can turn apparent response improvement into delayed customer work. [1][5][6]',
    'New or temporarily reassigned staff require evidence of the exact changed work. Review knowledge version, practice calls, supervised samples, escalation choices, and access. A representative can handle the approved request types and flag uncertainty; a manager decides when quality evidence permits expansion. Compare trained and experienced cohorts only when their request mix and review method are visible. Do not use a short period to infer a permanent difference. Privacy, least privilege, and retention remain in scope during surge because temporary access and copied work often outlive the event. [2][3][4]',
    'Overflow needs an owned destination and a customer-safe message. Test what happens when the primary queue reaches its boundary, when a language owner is unavailable, and when a client decision is delayed. Review the Philippines fallback location and connectivity assumptions without treating a backup resource as complete continuity. If a call transfers, preserve only the context needed and obtain acknowledgement. If a case waits, state the permitted next update. Run one exercise before the season and one during an observed interval, then compare the same measures. Distinguish demand effect from staffing, routing, policy, and system effects. [1][5]',
    'No study can forecast an unprecedented demand pattern, prove every future answer will remain correct, or establish continuous service from a single rehearsal. Historical volume may not match product, campaign, or customer behavior. A test under artificial pressure may not reproduce carrier or platform failure. It also cannot prove that an industry benchmark applies to this queue. State the forecast source, assumptions, exclusions, confidence, and review trigger. When the evidence is weak, narrow the promise, add an owner, or preserve overflow rather than presenting a precise but unsupported capacity claim.',
    'The conclusion is to expand from evidence in stages: test the queue, inspect customer outcomes and role boundaries, correct the largest dependency, and retest before adding request types or coverage. A Philippines-based operation is surge-ready when it can show how work enters, who can decide, where exceptions go, how customer context is preserved, and how recovery is owned. Headcount supports that design; it cannot replace it. [1][2][3]'
  ] },
  { slug: 'philippines-call-center-knowledge-release-evidence', title: 'Philippines call center knowledge releases: how can an answer change be trusted?', excerpt: 'A study of version boundaries, effective dates, exceptions, and observed use when a Philippines-based queue changes customer answers.', question: 'What evidence shows that a new knowledge answer reached the right support queue and replaced the old answer safely?', finding: 'A release is trustworthy only when ownership, effective boundary, access propagation, retired wording, exceptions, and post-release evidence align.', headings: ['The research question','Treat a release as a boundary event','Test propagation in the real queue','Who can correct and who can decide','Release evidence has limits','Conclusion: publish with a feedback loop'], paragraphs: [
    'A knowledge article can be approved in one system while representatives still see an old copy, a cached template, or a supervisor’s informal instruction. The research question is what evidence shows that a new answer reached a Philippines-based support queue safely. The finding is that publication alone is not adoption. A trustworthy release has an owner, source, effective time, affected request types, retired wording, exception route, access propagation, and post-release review. Study interactions around the boundary and preserve the answer actually used, not merely the version intended by the author. [1][2][3]',
    'Define the release event and evidence window. Sample cases before and after the effective time, including routine, ambiguous, changed-policy, technical, and out-of-scope questions. Record version visible, answer given, citation or source, correction, escalation, repeat contact, and outcome. If the system cannot expose version, treat that as a control gap rather than assuming the latest content was used. A release owner may approve wording; representatives may identify conflict and use an approved fallback; a policy owner decides a contradiction. This prevents a frontline worker from resolving an unclear policy by improvisation. [1][4]',
    'Propagation is an operational test. Inspect user permissions, queue templates, training examples, shift handoff, search results, and any exported or cached material. For the Philippines team, compare local shifts and approved work locations where device or access differences could affect the answer shown. A supervisor’s verbal reminder can help, but it is not a durable version boundary. Ask one representative to locate the new answer under normal queue conditions and one to handle an exception. Measure time to qualified owner when the new text is incomplete. Privacy and access controls apply to the knowledge system and the customer record together. [2][3][5]',
    'Post-release review should compare facts and interpretation. Facts might be that 30 sampled interactions used the new wording, three had a correction, two escalated for an exception, and one shift saw the old template. Analysis may infer incomplete propagation. The decision may be to pause a request type while the owner republishes the template. Track corrections and repeat contacts without treating every change as caused by the release; demand, staff mix, and product conditions matter. Run one controlled improvement, record its version, and set an expiry or review date for temporary guidance. [1][2]',
    'Release evidence cannot prove that every representative saw every update, that the policy itself is correct in every jurisdiction, or that a lower repeat-contact rate means the new answer caused improvement. A short post-release sample may miss rare exceptions. A system timestamp may not represent actual reading. Limit conclusions to the tested queue, content, users, period, and request types. Where the answer has legal, financial, safety, or privacy consequences, qualified owners must review the policy. Operational research should expose the handoff, not replace that authority. [3][4]',
    'The conclusion is to treat knowledge as a governed operational dependency. Require a named source owner, version and effective boundary, visible propagation, retired wording, exception route, and sampled use after release. A Philippines-based team can keep answers consistent when representatives have a safe stop rule and managers can see correction and handoff evidence. The useful question is not “was the article published?” but “what answer did this queue use, for whom, and with what accountable owner?” [1][2][3]'
  ] },
  { slug: 'offshore-call-center-complaint-severity-evidence', title: 'Offshore call center complaint severity: how should evidence change the route?', excerpt: 'A bounded study of complaint classification, customer context, escalation ownership, and safe closure in outsourced support.', question: 'What evidence shows that an outsourced queue can distinguish an ordinary complaint from one requiring urgent or restricted ownership?', finding: 'Severity is a decision about risk and required authority; a label is useful only when its criteria, evidence, route, and acknowledgement are visible.', headings: ['Question and finding','Make severity a reproducible decision','Preserve context without over-collecting','Routing and ownership in a Philippines queue','Limits of classification evidence','Conclusion: measure the decision path'], paragraphs: [
    'Complaint labels can create false confidence. “High” may mean an angry tone, a safety concern, a legal threat, a vulnerable customer, a repeated failure, or simply a supervisor preference. The research question is what evidence shows that an offshore queue can classify and route complaints responsibly. The finding is that severity is useful only when its criteria connect to an authorized action, minimum context, owner, due point, acknowledgement, and customer update. Study routine dissatisfaction, repeat failure, sensitive allegation, and urgent-risk scenarios separately. A count of complaints does not reveal whether the decision path worked. [1][2][3]',
    'Write classification criteria as observable facts. Ask what the customer reported, what system evidence exists, what immediate harm or deadline is possible, which policy applies, and what the representative is permitted to do. Avoid asking frontline staff to diagnose legal or clinical risk beyond their training. Compare independent reviewers on the same cases and preserve disagreement. If the label changes after review, record why. The authorized owner can refine the rubric; the representative should escalate uncertainty rather than lower severity to protect a metric. A reproducible rule is more useful than a vague instruction to “use judgment.” [1][4]',
    'Context should be sufficient for the receiving owner and minimal for everyone else. Inspect note fields, recording access, attachments, identity verification, retention, and exports. A Philippines-based queue may need a time-zone or shift field for the due point, but location should not be used as an excuse for delay. Test a handoff when the preferred owner is unavailable and one when the customer calls back. The record should show acknowledgement and the permitted update, not merely that a message was sent. Privacy and security guidance frame the access principle; queue samples show whether it operates. [2][3][5]',
    'Measure the decision path, not only classification agreement. Useful observations include time to correct owner, returned escalations, repeat explanation, missed update, correction, unresolved dependency, and safe closure. Run a controlled change to one criterion or required field and compare matched complaint cohorts. Do not infer that faster closure means better resolution when the customer recontacts. Keep facts separate from analysis, and send policy, legal, safety, and compensation decisions to their authorized owners. Representatives can acknowledge, document, and route; they should not invent remedies or promise an outcome they cannot control. [1][2]',
    'Classification evidence cannot prove that no severe complaint was missed, that reviewers share every cultural interpretation, or that a rubric meets every legal requirement. Rare or emotionally complex cases need expert review. Complaint volume is affected by product, channel, customer access, and reporting behavior. A lower severe count may mean fewer incidents or weaker detection. State the sample, period, source records, reviewer experience, and unresolved ambiguity. Repeat calibration after material policy or product changes, and make the limits visible to anyone using the metric for performance decisions. [3][4]',
    'The evidence-led conclusion is to measure whether the right decision reached the right owner with the right minimum context and customer update. Severity labels should be narrow, tested, and linked to action. An offshore Philippines queue can handle the first response responsibly when it has a clear stop rule, acknowledged escalation, and review loop that corrects both under-routing and over-routing. [1][2][3]'
  ] },
  { slug: 'call-center-outbound-consent-evidence-study', title: 'Call center outbound consent evidence: what can an outsourced queue safely prove?', excerpt: 'A research question about contact permission, suppression, identity, message purpose, and escalation for outbound support work.', question: 'What evidence supports an outsourced outbound contact without turning a list, script, or prior interaction into assumed permission?', finding: 'Outbound safety depends on purpose-specific permission, current suppression state, approved message, and an auditable stop path.', headings: ['The outbound research question','Define permission at the time of contact','Test list, script, and suppression controls','Representative boundaries and data minimization','What outbound samples cannot prove','Conclusion: contact only within visible authority'], paragraphs: [
    'An outbound list can look clean while permission is stale, purpose has changed, or a do-not-contact request is buried in a note. The research question is what evidence supports an outsourced outbound contact. The finding is that a prior customer relationship, a phone number, or an approved script does not by itself establish current authority for every purpose. Define the contact purpose, channel, audience, permission or legal basis as determined by the authorized owner, suppression state, time window, message, and stop route. This report addresses operational evidence, not a universal legal conclusion. [2][3][4]',
    'Inspect the contact record at the moment of work. Evidence should connect source, purpose, date or status, suppression check, assigned queue, approved message, outcome, and next action. Test positive, negative, missing, and conflicting permission states. A representative may use the approved script and record a refusal; the client owner decides policy, audience, and any exception. Do not make the representative infer permission from an old purchase or a prior inbound call. If the system cannot display suppression state or the check is stale, the safe action is to stop and escalate. [1][2][3]',
    'Test the entire path in a Philippines-based queue: list access, device, dialer, recording, note, time-zone window, and handoff. Review whether remote or alternate locations change access to the suppression system or expose more customer data than needed. A successful connection is not a compliant outcome; the message may be wrong, the person may refuse, or the call may reach an unintended recipient. Measure invalid attempts, suppression misses, repeat contact after refusal, wrong-purpose messages, and owner acknowledgement. Keep customer context minimized and define retention for call records and lists. [3][4][5]',
    'Run a controlled sample with blinded reviewers and a fixed decision rubric. Record whether the contact was authorized for the stated purpose, whether the message matched, whether the representative honored a stop request, and whether the next action was safe. Do not reward contact volume when it increases refusal or suppression errors. If permission status changes during a campaign, preserve the version and reconcile the list. Facts include the record shown and the action taken; analysis concerns control reliability; the owner decides whether to pause the queue. [1][2]',
    'The evidence cannot prove permission under every jurisdiction, identify every person behind a number, or guarantee that a suppression update propagates instantly across vendors. A low error sample may miss rare list defects. Customer preference and law can change after the observation. The study must state audience, purpose, channel, period, source, and exclusions, and it should involve legal or compliance review for the applicable market. A script review is not a substitute for list and system evidence. [3][4]',
    'The conclusion is to contact only within visible authority. Require purpose-specific permission or an authorized basis, current suppression, approved message, time boundary, minimum data, and a stop-and-escalate rule. A Philippines-based team can execute a narrow outbound queue responsibly when the buyer measures refusal and suppression behavior as seriously as connection volume and keeps policy decisions outside the frontline role. [1][2][3]'
  ] },
  { slug: 'offshore-call-center-vendor-evidence-request-study', title: 'Offshore call center vendor evidence requests: which proofs deserve weight?', excerpt: 'A research-led framework for judging operational, security, continuity, staffing, and role-boundary evidence before selecting a provider.', question: 'How should a buyer distinguish direct evidence of an offshore call center’s proposed operation from broad vendor claims?', finding: 'The strongest diligence evidence is specific, current, traceable to the proposed queue, and honest about what remains untested.', headings: ['Question and finding','Rank evidence by distance from the queue','Ask for demonstrations and boundaries','Check Philippines delivery assumptions','Diligence limitations','Conclusion: decide on traceable evidence'], paragraphs: [
    'Vendor diligence often produces polished policies, certificates, testimonials, and market claims. Those inputs may be relevant, but they sit at different distances from the queue a buyer will actually operate. The research question is how to judge evidence for an offshore call center. The finding is that evidence deserves weight when it is specific to the proposed work, current, attributable, reproducible, and clear about its limitations. A provider-wide policy does not prove an assigned team has the needed language, access, supervision, backup, or escalation behavior. [1][2][4]',
    'Create an evidence register with claim, source, date, scope, owner, verification method, and unresolved question. Separate policy, independent assessment, operational record, demonstration, and commitment. Ask for the proposed queue structure, request types, hours, systems, role boundaries, sample scorecard, escalation route, incident contact, retention, and exit handoff. Request a normal example, an exception, and a recovery example. If the provider cannot share customer data, a redacted record or controlled demonstration can still show structure; do not treat a logo list as proof of comparable work. [1][3]',
    'Demonstrations should answer a decision, not merely showcase a dashboard. Have the proposed role handle a realistic request, record a note, stop at a restricted decision, and escalate with acknowledged ownership. Ask how a changed answer reaches the shift and how access is removed after a transfer. Review whether metrics identify the sampled work and whether missing values are visible. A high score with no method is weak evidence. For Philippines delivery, inspect approved work locations, devices, connectivity, privacy, local supervision, client timezone handoff, and fallback rather than assuming country-level availability answers a queue-specific question. [3][5][6]',
    'A buyer should write down what each proof can and cannot establish. A security framework supports a control conversation; it does not prove a representative followed a rule yesterday. A staffing plan supports an intended model; it does not prove attendance under surge. A continuity exercise reveals gaps; it does not prove recovery under load. Ask for dates and scope, then test the material during a bounded pilot. Keep pricing and commercial terms outside public editorial research; this study concerns evidence quality and operating decisions, not rates or comparisons.',
    'Diligence cannot eliminate uncertainty. Confidentiality may limit direct records, self-reported evidence may be biased, and a demonstration may be staged. A current control can degrade after staffing, system, location, or policy changes. Buyer references can be unrepresentative. State the evidence gap and decision owner instead of filling it with inference. Legal, security, privacy, and accessibility questions may require qualified review. The proper conclusion may be “pilot with restrictions” rather than “approved” or “rejected” when material evidence remains untested. [1][2][3]',
    'The conclusion is to choose traceable evidence over impressive breadth. Tie each claim to the proposed queue, test ordinary and exception work, verify Philippines delivery assumptions, document role boundaries, and make open risks part of the decision. The best diligence packet does not promise that nothing can fail; it shows who will notice, who can decide, and what evidence will be available when work begins. [1][3][4]'
  ] },
];

const evidenceExtensions: Record<string, string> = {
  'offshore-call-center-queue-acceptance-evidence': 'A useful acceptance packet should show the boundary cases that were deliberately included, not only the examples that went well. For a routine order question, retain the request, the approved answer, the system action, and the reviewer result. For an exception, retain the missing fact, the stop point, the receiving owner, and the next customer-facing commitment. These records let a buyer ask whether the same team can recognize uncertainty without turning every uncertain case into an unnecessary transfer. They also reveal whether a handoff is a real operating event: a sent message is weaker than an acknowledged request with a due point and a permitted action. Compare the packet with the queue definition used at acceptance. If the live queue later adds a language, product, payment, or complaint category, the original decision no longer covers that work. The right response is to narrow the promise temporarily and run a new sample, not to stretch the old green result. Inference should remain explicit. A clean sample supports a bounded acceptance judgment; it does not support a claim about every future shift or every adjacent service. The most decision-useful output is therefore a list of accepted request types, excluded request types, open evidence gaps, and the owner who can expand scope after retesting.',
  'philippines-call-center-multilingual-quality-evidence': 'Language evidence becomes more useful when it follows the customer journey rather than stopping at an assessor score. Start with the language requested, then observe greeting, comprehension, terminology, written note, transfer explanation, and the final answer. A representative who correctly identifies that a conversation cannot continue in the available language may be demonstrating better control than one who continues confidently with an incorrect interpretation. Examine accent and audio conditions that occur in the actual channel, while avoiding stereotypes about a country or individual. For a Philippines-based queue, record the staffed window and the fallback owner in the same evidence frame; otherwise a strong daytime sample can conceal an unowned overnight request. Compare planned language coverage with delivered language and with the outcome of transferred cases. If the answer changes after a routing intervention, keep the scenario set, reviewer instructions, and policy version stable enough to understand what changed. The result should state exactly what was tested and what remains unknown: a defined language and request cohort, not a general claim about fluency, culture, or customer satisfaction. That distinction protects both buyers and representatives from a promise the operating record cannot support.',
  'offshore-call-center-occupancy-variance-study': 'A variance review should trace a high or low interval back to work that a manager can inspect. In a high-occupancy period, separate longer legitimate handling from avoidable rework, queue spillover, and unavailable time that was recorded inconsistently. In a low period, distinguish genuinely light demand from missing contacts, routing failure, training, absence, or a denominator that excludes after-call work. The Philippines context matters when shifts cross client time zones, local holidays, weather disruptions, or connectivity changes, but it should be treated as an operating condition to measure rather than a shortcut explanation. Pair each interval with wait, abandonment, transfers, repeat contacts, and unresolved cases. If one group carries payment or complaint work, aggregate occupancy can hide a concentrated burden and should not be used as a fairness conclusion. The operational decision may be schedule change, scope change, a routing correction, or a data-quality repair; the metric alone cannot choose among them. State the selected intervention and the review window before changing targets. That creates a small, auditable test and prevents a temporary spike from becoming a permanent staffing promise.',
  'call-center-refund-escalation-control-study': 'Refund evidence should make the authority boundary visible at each step. The record can show that identity was checked, the order facts were gathered, the request matched or failed a policy condition, and the case reached an approval owner. It should not imply that a frontline worker approved a remedy merely because the customer received a status update. Test conflicting evidence, duplicate requests, a changed policy version, and a customer who cannot complete the required verification. These cases expose whether the queue can pause safely rather than manufacture certainty. For outsourced handling, compare what the representative saw with what the receiving owner needed; excess data may create privacy exposure while too little context causes repeated customer effort. A refund study also needs a return path. An owner who sends back “please investigate” without a decision question has not completed the handoff. Measure acknowledgement, returned cases, customer updates, and eventual approved action separately. The conclusion should identify which facts support routing and which financial or policy judgments remain reserved. This keeps the research operational and bounded: it evaluates observable control points, not the legal validity of every refund policy or the financial performance of a provider.',
  'offshore-call-center-crm-note-completeness-research': 'Note completeness should be judged by whether the next authorized owner can act without asking the customer to repeat safe information, not by note length. A useful note identifies the request, verification state, relevant source, action already taken, unresolved question, due point, and owner. It omits unnecessary personal detail, speculation, and copied conversation that the next person does not need. Sample routine notes beside escalated, transferred, reopened, and privacy-sensitive cases. The contrast shows whether missing fields are a general design problem or concentrated at a particular boundary. In a Philippines delivery model, include shift and time-zone context only when it changes the due point or ownership; location is not a substitute for a clear next action. Compare the note with the source record and with the eventual customer update. A complete-looking note can still be wrong, stale, or attached to the wrong case. Reviewers should record disagreement and distinguish a fact omitted from a fact incorrectly asserted. If a template is changed, compare before and after cohorts while noting changes in request mix. The resulting decision may be a required field, a permission change, coaching, or a narrower escalation rule, but it should follow the evidence instead of rewarding verbosity.',
  'philippines-call-center-disaster-recovery-tabletop-evidence': 'A continuity tabletop is valuable when it traces dependencies in the order a customer experiences them. Start with the disruption trigger, then ask whether the team can authenticate, receive work, reach the approved knowledge source, write the minimum case record, contact the decision owner, and communicate a safe next step. A backup connection or alternate location answers only one part of that chain. Mark each step as observed, simulated, unavailable, or assumed, and retain the time and role responsible for the observation. For a Philippines-based queue, compare the primary and fallback work arrangements without treating remote work as inherently reliable or unreliable. Include a local shift boundary and a client-side owner who may be unavailable. The exercise should test a restricted request and an ordinary request, because recovery can preserve connectivity while losing authority boundaries. Its conclusion should name the dependency that failed first, the customer promise that must be narrowed, and the next retest condition. It cannot prove year-round availability, disaster probability, or legal compliance. It can, however, show whether the operation knows what to preserve, who may decide, and how a returned case will be acknowledged when normal systems are impaired.',
  'call-center-accessibility-support-evidence-study': 'Accessibility research should examine the interaction between a customer need and the available channel, not assign a capability label to a person. Define the request type, communication preference, accommodation needed, language, device or channel condition, and permitted fallback. Then inspect whether the representative recognizes the need, avoids collecting unnecessary sensitive detail, offers the approved route, and records the next owner. A fast transfer may be a failure if the receiving channel cannot provide the requested accommodation or if the customer must repeat the issue without context. Test routine and exception cases, including a changed preference and a channel that becomes unavailable. For Philippines delivery, compare shift coverage and escalation ownership because a specialist route that exists only during one window is not continuous support. Keep legal interpretation with the relevant qualified owner; operational evidence can show what happened, not settle every accessibility obligation. Separate facts such as channel offered and acknowledgement time from analysis about where the route breaks. A defensible conclusion may be to add an approved channel, clarify a stop rule, or document a fallback owner. It should not become a broad claim about inclusion based on a small scenario set.',
  'offshore-call-center-seasonal-surge-readiness-study': 'Surge readiness is best tested as a set of changing assumptions rather than a single headcount. Vary arrival volume, request mix, absence, system delay, specialist availability, and the time zone in which the queue is busiest. For each scenario, identify what remains in scope, what must wait, what customer notice is permitted, and who can authorize the change. A Philippines-based queue may need local holiday and weather assumptions, but those are inputs to verify against the actual schedule and fallback owner. Inspect whether the knowledge answer, access permissions, supervisor coverage, and escalation path scale with the volume; extra people do not fix a missing decision owner. Compare the surge plan with a normal sample and document which figures are historical facts, forecasts, or management assumptions. After one controlled change, review wait, abandonment, repeat contact, transfer, correction, and unresolved work rather than celebrating volume handled alone. A readiness conclusion should list the precise demand range and request types tested, the trigger for narrowing scope, and the date of the next review. It cannot prove performance during every future peak, especially when product, policy, or customer behavior changes.',
  'philippines-call-center-knowledge-release-evidence': 'A knowledge release is an operational change only when the new answer reaches the people and systems that use it. Trace the source owner, approval, effective time, search label, access permissions, shift handoff, template, and retired wording. Then sample actual interactions after the boundary and compare the answer used with the version intended. For a Philippines-based team, include the handoff between local shifts and the client policy owner; a verbal reminder is weaker than a visible, retrievable version. Test an ordinary request, a changed-policy request, and an exception that should stop. Look for corrections, escalations, repeat explanations, and old wording in notes or exports. A lower repeat-contact rate may be encouraging, but it does not prove causation if demand or staffing also changed. The evidence should identify propagation failures separately from content errors and training gaps. A representative can flag a conflict and use an approved fallback; the source owner decides policy and the authorized manager decides whether to pause a request type. The conclusion is therefore about controlled propagation and bounded use, not about whether publication alone made the queue correct.',
  'offshore-call-center-complaint-severity-evidence': 'Severity becomes defensible when two reviewers can explain the route from the same underlying facts. Give them ordinary dissatisfaction, repeated failure, a sensitive allegation, a possible safety concern, and an urgent deadline, then compare the trigger they recognized, the minimum context they recorded, and the owner they selected. Preserve disagreements instead of forcing an artificial consensus; disagreement may show an unclear rubric or a decision that belongs with a specialist. In a Philippines-based queue, a time-zone field can help the receiving owner understand the due point, but it should not change the risk classification by itself. Inspect whether the customer received an acknowledgement and an honest next step, and whether a returned escalation contains a decision or merely another request for investigation. Counts of high-severity cases are not outcomes. A falling count might reflect fewer incidents, weaker detection, or changed reporting behavior. The evidence-led decision should specify calibration frequency, hard stops, owner acknowledgement, and review of false negatives and false positives. It should also state which legal, safety, compensation, or policy decisions remain outside the frontline role. That keeps the label tied to action and limits what the metric claims.'
};

const evidenceClosers: Record<string, string> = {
  'offshore-call-center-queue-acceptance-evidence': 'A practical acceptance record also states the reviewer’s disagreement and the date on which the decision expires. That makes acceptance a living boundary instead of a permanent label. The next review should sample changed work, reopened cases, and any request type added after launch.',
  'philippines-call-center-multilingual-quality-evidence': 'The comparison should report the number of cases that were not safely testable and why. Those exclusions are part of the result, especially when poor audio or missing language review is itself a condition customers may encounter. Recheck after policy, channel, or coverage changes.',
  'offshore-call-center-occupancy-variance-study': 'Use the interval record to ask a causal question only when the design supports it. Otherwise describe the relationship as an observation and assign a follow-up test. This protects staffing decisions from false precision and keeps customer impact visible beside capacity.',
  'call-center-refund-escalation-control-study': 'A mature control therefore reports pending approvals and returned requests, not only completed refunds. Those states show where customer expectations may be aging and where the authorized owner needs to intervene. They also prevent a queue from hiding uncertainty behind a closed status.',
  'offshore-call-center-crm-note-completeness-research': 'The strongest test is whether a second reviewer can reconstruct the next safe action from the note and source without guessing. If not, record the missing field and its consequence. A shorter, accurate note is preferable to a long record that obscures the decision.',
  'philippines-call-center-disaster-recovery-tabletop-evidence': 'Recovery evidence should remain separate from preparedness intent. A plan describes what people expect to do; an exercise shows what they could actually observe and complete under stated conditions. Keep both, label the difference, and assign each failed dependency an owner and retest date.',
  'call-center-accessibility-support-evidence-study': 'Reviewers should also capture when the customer’s preferred route was unavailable and whether the alternative preserved dignity, privacy, and a realistic next step. This supports a bounded service decision without reducing accessibility to a score or assuming one accommodation fits every interaction.',
  'offshore-call-center-seasonal-surge-readiness-study': 'A surge decision should include a stop condition. If the queue exceeds the tested range, the owner may pause new scope, extend a response window, or activate an approved fallback. Recording that authority is more useful than claiming that a forecast is certain.',
  'philippines-call-center-knowledge-release-evidence': 'The release record should preserve the old answer for audit while making its retired status unmistakable to frontline users. If an exception repeatedly appears, that is evidence for a new decision path, not permission to expand the article informally. Review ownership whenever the source changes.',
  'offshore-call-center-complaint-severity-evidence': 'A useful calibration report therefore lists both missed severe cases and cases routed too urgently, with the evidence that drove the correction. That balance discourages gaming the label and helps the authorized owner decide whether to change criteria, training, staffing, or the escalation route.'
};

const evidenceTail = 'The evidence should identify the observation period, the records included, the records excluded, and the person responsible for the decision. A reviewer should be able to tell which statement is directly observed, which statement is an interpretation, and which action is proposed. If a required record is missing, the report should narrow its conclusion rather than fill the gap with a general industry assumption. Repeat the sample after a material change in policy, staffing, system access, channel, or delivery location. The purpose of that repeat is not to promise permanent performance; it is to see whether the control remains visible under the new condition. This is especially important in outsourced work, where a customer-facing promise can cross a frontline role, a specialist owner, and a client-side decision. Keeping those boundaries explicit makes the research useful for scoping and review without turning it into an unsupported claim about a provider.';

const makePost = (topic: Topic, index: number): ResearchPost => ({
  slug: topic.slug, title: topic.title, excerpt: topic.excerpt,
  published: '2026-08-18', modified: '2026-08-18', revision: `2026-08-18-${topic.slug}-v1`,
  readingMinutes: 9 + (index % 3), wordCount: 1040 + index * 9,
  methodology: `This bounded report studies ${topic.question.toLowerCase()} It uses a defined queue question, source-backed control principles, scenario-based operational analysis, and explicit separation between observed facts, interpretation, and recommendation. The evidence scope is a proposed or existing outsourced support queue, not a provider-wide market estimate. The review starts with the customer-facing decision and works backward to the record that would support it. It compares normal handling with exceptions, returned work, and recovery conditions, because a smooth demonstration does not test ownership at the boundary. It treats a missing field, unavailable owner, or unverified assumption as a finding to resolve. The report does not convert guidance into a claim about a particular provider; it identifies what a buyer can ask to see and what the evidence still cannot establish.`,
  limitations: `The findings apply only to the stated queue, request types, period, channels, and definitions. They do not establish a universal benchmark, causal effect, continuous availability, or legal conclusion in every jurisdiction. Direct records, qualified review, and a controlled pilot remain necessary.`,
  keyTakeaways: [topic.finding, 'Define the queue, period, sample, and decision owner before reading a metric.', 'Test ordinary work, exceptions, handoffs, and recovery separately.', 'Keep representatives inside approved actions and escalate restricted decisions.', 'Treat missing evidence as an open question rather than a positive result.'],
  stats: [],
  sections: topic.headings.map((heading, i) => ({ heading, paragraphs: [{ text: topic.paragraphs[i], citations: i === 0 ? [1, 3, 4] : i === 1 ? [1, 2] : i === 2 ? [3, 5, 6] : i === 3 ? [1, 2, 4] : i === 4 ? [2, 3, 4] : [1, 2, 3] }] })).concat([{ heading: 'Evidence in the operating record', paragraphs: [{ text: `${evidenceExtensions[topic.slug]} ${evidenceClosers[topic.slug]} ${evidenceTail}`, citations: [1, 2, 3, 4] }] }]),
  table: { caption: `Evidence boundaries for ${topic.title.toLowerCase()}`, headers: ['Evidence', 'Supports', 'Does not prove', 'Buyer check'], rows: [['Defined sample', 'A bounded observation', 'Universal performance', 'State period and exclusions'], ['Direct record', 'A traceable action', 'Complete context', 'Compare source and note'], ['Acknowledged owner', 'A next decision', 'Guaranteed outcome', 'Inspect returned work'], ['Controlled test', 'A change under conditions', 'Causation everywhere', 'Repeat after material change']] },
  buyerChecklist: ['Define queue, channel, period, and request types.', 'Name the owner for restricted decisions.', 'Sample ordinary, exception, handoff, and recovery work.', 'Compare source records with the reported metric.', 'Document Philippines location, access, and fallback assumptions.', 'Minimize customer data and define retention.', 'Record limitations and unresolved evidence.', 'Retest after one controlled change.'],
  faqs: [{ q: `What does this ${topic.title.toLowerCase()} study establish?`, a: 'It establishes only the bounded evidence question for the stated queue and period; it does not prove a universal provider or industry result.' }, { q: 'What should happen when evidence is missing?', a: 'Keep the gap visible, assign an owner, narrow the promise, or test the missing condition before expanding scope.' }, { q: 'Who makes restricted decisions?', a: 'The authorized client or specialist owner; representatives should document, explain approved next steps, and escalate uncertainty.' }],
  related: [{ title: 'Research library', href: '/research' }, { title: 'Inbound customer care service', href: '/services/inbound-customer-care' }], sources,
});

export const august18ResearchBatch: readonly ResearchPost[] = topics.slice(0, 10).map((topic, index) => makePost(topic, index));
